'use strict';
// The AWS and Azure icon data (#534): one generated file, data/cloud-icons.json, shipped once per package
// and read by the extension bundle, the MCP server bundle and the render CLI at first use
// (src/assets/cloudIcons.ts). The generators call writeCloudIconData; it also writes the SHA-256 the
// bundles are built against (src/assets/cloudIconsDigest.ts) and a test keeps the two equal.
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const DATA_FILE = path.join(ROOT, 'data', 'cloud-icons.json');
const DIGEST_FILE = path.join(ROOT, 'src', 'assets', 'cloudIconsDigest.ts');
const VENDORS = ['aws', 'azure'];

function sha256(buffer) {
  return crypto.createHash('sha256').update(buffer).digest('hex');
}

/** The file text for `{ aws: {id: sprite}, azure: {id: sprite} }`: one sprite per line, stable for review diffs. */
function serialise(data) {
  const sections = VENDORS.map(vendor => {
    const lines = Object.entries(data[vendor] ?? {}).map(([id, sprite]) => `${JSON.stringify(id)}:${JSON.stringify(sprite)}`);
    return `${JSON.stringify(vendor)}:{\n${lines.join(',\n')}\n}`;
  });
  return `{\n${sections.join(',\n')}\n}\n`;
}

function readCloudIconData(file = DATA_FILE) {
  return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : { aws: {}, azure: {} };
}

/** Replace one vendor's sprites (the other vendor is kept), rewrite the file and its digest module. */
function writeCloudIconData(vendor, sprites, { file = DATA_FILE, digestFile = DIGEST_FILE } = {}) {
  if (!VENDORS.includes(vendor)) throw new Error(`Unknown icon vendor ${vendor}`);
  const data = readCloudIconData(file);
  data[vendor] = sprites;
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const text = serialise(data);
  fs.writeFileSync(file, text);
  fs.writeFileSync(digestFile, digestModule(sha256(Buffer.from(text, 'utf8'))));
  return text;
}

function digestModule(digest) {
  return `// Generated by scripts/cloud-icon-data.js with data/cloud-icons.json; do not edit.\n// The SHA-256 of that file's bytes. Bundles check the file they read against it (src/assets/cloudIcons.ts).\nexport const CLOUD_ICONS_SHA256 = '${digest}';\n`;
}

module.exports = { DATA_FILE, DIGEST_FILE, VENDORS, digestModule, readCloudIconData, serialise, sha256, writeCloudIconData };
